1	// SPDX-License-Identifier: Apache-2.0
2	//! The OpenAI Responses streaming protocol (spec D10–D13, § 6.3–§ 6.6).
3	//!
4	//! One hold per response (D10): it opens at the first client-run `output_item.added` and
5	//! completes at the terminal event, with every client-run call of the response. Every frame of a
6	//! client-run item, and the terminal frame of a response whose hold opened, touch
7	//! [`HoldKey::Response`]; no other frame touches anything. Once the hold opens, every later frame waits behind it in the interceptor's FIFO
8	//! (749 D12), the frames of provider-run items included.
9	//!
10	//! Output is re-framed with an `event: <data.type>` line (D11). A frame that holds no blocked item
11	//! keeps its payload bytes. A blocked item is rewritten frame by frame (§ 6.5): its `added` frame
12	//! becomes three events, its middle frames are dropped, and its `done` frame becomes the completed
13	//! message. When the item has no `done` frame, the `output_item.done` event is synthesized before
14	//! the next frame that ends the item: the terminal event, `[DONE]`, an upstream error record, EOF
15	//! ([`Protocol::closing`]) or the D13 frame ([`Protocol::closing_on_abort`]). In the terminal
16	//! event, the item at each blocked index is replaced with the completed message.
17	
18	use std::collections::HashSet;
19	
20	use bytes::Bytes;
21	use serde_json::Value;
22	
23	use crate::protocol::{Frame, Protocol, Step, StepError, Verdict, Verdicts};
24	use crate::report::notice_line;
25	use crate::responses::assembly::Assembly;
26	use crate::responses::classify::{Event, Scope, classify, scope_of};
27	use crate::responses::rewrite::{added_events, completed_message, done_event};
28	use crate::sse::{self, Record};
29	use crate::types::{BlockCode, HoldKey};
30	
31	/// The longest `event:` name written, in bytes (Review Focus 1).
32	const MAX_EVENT_BYTES: usize = 64;
33	
34	/// The `output_item.done` that a blocked item still owes the client: its rewritten `added` frame
35	/// went out, its `done` frame did not.
36	struct Owed {
37	    index: u32,
38	    notice: String,
39	    /// The `sequence_number` of the item's `added` frame, repeated as the rewrite repeats it.
40	    seq: Option<Value>,
41	}
42	
43	pub(crate) struct ResponsesStream {
44	    asm: Assembly,
45	    /// The hold was handed to the decider at the terminal event.
46	    completed: bool,
47	    owed: Option<Owed>,
48	    /// The blocked items whose `output_item.done` the client already has.
49	    closed: HashSet<u32>,
50	}
51	
52	impl ResponsesStream {
53	    /// `cap` is the stream's `max_held_bytes` (749 D13).
54	    pub(crate) fn with_cap(cap: usize) -> Self {
55	        ResponsesStream {
56	            asm: Assembly::with_cap(cap),
57	            completed: false,
58	            owed: None,
59	            closed: HashSet::new(),
60	        }
61	    }
62	
63	    /// The notice of the call in `slot`, by its qualified name (§ 6.6).
64	    fn notice(&self, slot: usize, code: BlockCode) -> String {
65	        let known = self.asm.known();
66	        let name = known.get(slot).map_or("unknown", |(_, n)| n.as_str());
67	        notice_line(name, code)
68	    }
69	
70	    /// The synthesized `output_item.done` of the owed item, if any (§ 6.5).
71	    fn owed_done(&mut self) -> Vec<Bytes> {
72	        let Some(o) = self.owed.take() else { return Vec::new() };
73	        self.closed.insert(o.index);
74	        vec![event_frame(&done_event(o.index, &o.notice, o.seq.as_ref()))]
75	    }
76	
77	    /// One frame of the client-run item at `index`, which the verdict blocks with `code`.
78	    fn rewrite_item(&mut self, value: &Value, index: u32, slot: usize, code: BlockCode) -> Vec<Bytes> {
79	        let seq = value.get("sequence_number");
80	        match value.get("type").and_then(Value::as_str) {
81	            Some("response.output_item.added") => {
82	                let notice = self.notice(slot, code);
83	                let out = added_events(index, &notice, seq).iter().map(event_frame).collect();
84	                self.owed = Some(Owed { index, notice, seq: seq.cloned() });
85	                out
86	            }
87	            Some("response.output_item.done") if !self.closed.contains(&index) => {
88	                if self.owed.as_ref().is_some_and(|o| o.index == index) {
89	                    self.owed = None;
90	                }
91	                self.closed.insert(index);
92	                vec![event_frame(&done_event(index, &self.notice(slot, code), seq))]
93	            }
94	            _ => Vec::new(),
95	        }
96	    }
97	
98	    /// The terminal event with every blocked index replaced by its completed message. `None` when
99	    /// nothing in it is blocked.
100	    fn rewrite_terminal(&self, value: &Value, verdict: &Verdict) -> Option<Value> {
101	        let mut v = value.clone();
102	        let output = v.get_mut("response").and_then(|r| r.get_mut("output")).and_then(Value::as_array_mut)?;
103	        let mut changed = false;
104	        for (slot, (index, name)) in self.asm.known().iter().enumerate() {
105	            let Some(code) = verdict.block_code(slot) else { continue };
106	            if let Some(item) = output.get_mut(*index as usize) {
107	                *item = completed_message(*index, &notice_line(name, code));
108	                changed = true;
109	            }
110	        }
111	        changed.then_some(v)
112	    }
113	}
114	
115	/// D11 and Review Focus 1: an `event:` name only when it is `^[a-z0-9_.]{1,64}$`.
116	fn safe_event(t: &str) -> bool {
117	    (1..=MAX_EVENT_BYTES).contains(&t.len()) && t.bytes().all(|b| b.is_ascii_lowercase() || b.is_ascii_digit() || b == b'_' || b == b'.')
118	}
119	
120	/// The `event:` name of a payload: its `data.type`, when that is a safe name.
121	fn event_of(v: &Value) -> Option<&str> {
122	    v.get("type").and_then(Value::as_str).filter(|t| safe_event(t))
123	}
124	
125	/// One gateway-built event, framed with its type.
126	fn event_frame(v: &Value) -> Bytes {
127	    sse::frame(event_of(v), &serde_json::to_vec(v).expect("a Value always serializes"))
128	}
129	
130	impl Protocol for ResponsesStream {
131	    fn step(&mut self, rec: Record, _verdicts: &Verdicts) -> Result<Step, StepError> {
132	        // R3: after the terminal event only `[DONE]` may follow. Checked first, so a malformed
133	        // late record cannot become a failure either.
134	        if self.asm.ended() && rec.data != b"[DONE]" {
135	            return Err(StepError::AfterEnd);
136	        }
137	        let (ty, value) = match classify(&rec)? {
138	            Event::Done => {
139	                return Ok(Step::End(Frame {
140	                    event: None,
141	                    payload: rec.data,
142	                    value: None,
143	                    touches: Vec::new(),
144	                }));
145	            }
146	            Event::UpstreamError(value) => {
147	                return Ok(Step::UpstreamError(Frame {
148	                    event: None,
149	                    payload: rec.data,
150	                    value: Some(value),
151	                    touches: Vec::new(),
152	                }));
153	            }
154	            Event::Known { ty, value } => (ty, value),
155	        };
156	        let effect = self.asm.accept(ty, &value)?;
157	        // The terminal frame carries the hold's calls in `output`, once the hold has opened.
158	        let holds = effect.item.is_some() || (effect.terminal && self.asm.hold_open());
159	        let touches = if holds { vec![HoldKey::Response] } else { Vec::new() };
160	        let frame = Frame {
161	            event: Some(ty),
162	            payload: rec.data,
163	            value: Some(value),
164	            touches,
165	        };
166	        if effect.terminal {
167	            let mut completed = Vec::new();
168	            if self.asm.hold_open() && !self.asm.hold_cut() {
169	                self.completed = true;
170	                completed.push((HoldKey::Response, self.asm.hold_calls()));
171	            }
172	            return Ok(Step::Terminal { frame, completed });
173	        }
174	        Ok(Step::Frame {
175	            frame,
176	            opened: if effect.opened { vec![HoldKey::Response] } else { Vec::new() },
177	            completed: Vec::new(),
178	            reports: effect.report.into_iter().collect(),
179	        })
180	    }
181	
182	    fn incomplete(&self) -> Vec<HoldKey> {
183	        if self.asm.hold_cut() && !self.completed { vec![HoldKey::Response] } else { Vec::new() }
184	    }
185	
186	    fn release(&mut self, frame: Frame, verdicts: &Verdicts) -> Vec<Bytes> {
187	        let Some(value) = frame.value else {
188	            let mut out = self.owed_done();
189	            out.push(sse::frame(None, &frame.payload));
190	            return out;
191	        };
192	        let original = || sse::frame(event_of(&value), &frame.payload);
193	        let verdict = verdicts.get(&HoldKey::Response).filter(|v| v.blocks_any());
194	        if !frame.touches.contains(&HoldKey::Response) {
195	            // A keepalive or a response-level event may sit inside an item (R5 is about items);
196	            // any other frame here ends the open item: an upstream error record.
197	            let inside = frame.event.map(scope_of).is_some_and(|s| matches!(s, Scope::Keepalive | Scope::ResponseLevel));
198	            let mut out = if inside { Vec::new() } else { self.owed_done() };
199	            out.push(original());
200	            return out;
201	        }
202	        let Some(verdict) = verdict else { return vec![original()] };
203	        if frame.event.map(scope_of) == Some(Scope::Terminal) {
204	            let mut out = self.owed_done();
205	            out.push(match self.rewrite_terminal(&value, verdict) {
206	                Some(v) => event_frame(&v),
207	                None => original(),
208	            });
209	            return out;
210	        }
211	        let index = value.get("output_index").and_then(Value::as_u64).and_then(|i| u32::try_from(i).ok());
212	        let blocked = index.and_then(|i| self.asm.slot_of(i).map(|s| (i, s))).and_then(|(i, s)| verdict.block_code(s).map(|c| (i, s, c)));
213	        match blocked {
214	            Some((i, slot, code)) => self.rewrite_item(&value, i, slot, code),
215	            None => vec![original()],
216	        }
217	    }
218	
219	    fn closing(&mut self, _verdicts: &Verdicts) -> Vec<Bytes> {
220	        self.owed_done()
221	    }
222	
223	    fn closing_on_abort(&mut self, _verdicts: &Verdicts) -> Vec<Bytes> {
224	        self.owed_done()
225	    }
226	
227	    fn known_calls(&self, hold: HoldKey) -> Vec<(u32, String)> {
228	        match hold {
229	            HoldKey::Response => self.asm.known(),
230	            HoldKey::Choice(_) | HoldKey::Block(_) => Vec::new(),
231	        }
232	    }
233	
234	    /// Pass-through framing (P-4): the `event:` line names `data.type` when it is a safe name.
235	    fn unframed(&self, rec: Record) -> Bytes {
236	        let value: Option<Value> = serde_json::from_slice(&rec.data).ok();
237	        sse::frame(value.as_ref().and_then(event_of), &rec.data)
238	    }
239	
240	    #[cfg(test)]
241	    fn retained(&self) -> usize {
242	        self.asm.retained()
243	    }
244	}
