296	    /// One item: its events and its `done` item.
297	    type Item = (Vec<Value>, Value);
298	
299	    fn function_item(i: u32, item: Value, deltas: &[&str]) -> Item {
300	        let id = item["id"].as_str().unwrap().to_owned();
301	        let mut evs = vec![added(i, &item)];
302	        for d in deltas {
