310	    fn message_item(i: u32, id: &str, text: &str) -> Item {
311	        let part = json!({"type": "output_text", "text": text, "annotations": []});
312	        let done = json!({"type": "message", "id": id, "status": "completed", "role": "assistant", "content": [part]});
313	        let open = json!({"type": "message", "id": id, "status": "in_progress", "role": "assistant", "content": []});
314	        let evs = vec![
315	            json!({"type": "response.output_item.added", "output_index": i, "item": open}),
316	            json!({"type": "response.content_part.added", "output_index": i, "item_id": id, "content_index": 0, "part": {"type": "output_text", "text": "", "annotations": []}}),
317	            json!({"type": "response.output_text.delta", "output_index": i, "item_id": id, "content_index": 0, "delta": text}),
318	            json!({"type": "response.output_text.done", "output_index": i, "item_id": id, "content_index": 0, "text": text}),
319	            json!({"type": "response.content_part.done", "output_index": i, "item_id": id, "content_index": 0, "part": part}),
320	            item_done(i, &done),
321	        ];
322	        (evs, done)
