325	    fn web_search_item(i: u32, id: &str) -> Item {
326	        let done = json!({"type": "web_search_call", "id": id, "status": "completed", "action": {"type": "search", "query": "q"}});
327	        let evs = vec![
328	            json!({"type": "response.output_item.added", "output_index": i, "item": {"type": "web_search_call", "id": id, "status": "in_progress"}}),
329	            json!({"type": "response.web_search_call.in_progress", "output_index": i, "item_id": id}),
330	            json!({"type": "response.web_search_call.completed", "output_index": i, "item_id": id}),
