336	    /// `created`, `in_progress`, the items, the terminal event with their `done` items.
337	    fn stream_of(items: Vec<Item>, terminal_type: &str) -> Vec<Value> {
338	        let mut evs = vec![lifecycle("response.created", json!([])), lifecycle("response.in_progress", json!([]))];
339	        let mut output = Vec::new();
340	        for (e, d) in items {
341	            evs.extend(e);
342	            output.push(d);
343	        }
344	        evs.push(terminal(terminal_type, output));
345	        evs
346	    }
