348	    /// Give every event the `sequence_number` 0, 1, 2, … (R7).
349	    fn numbered(evs: Vec<Value>) -> Vec<Value> {
350	        evs.into_iter()
351	            .enumerate()
352	            .map(|(i, mut e)| {
353	                e["sequence_number"] = json!(i);
354	                e
355	            })
356	            .collect()
357	    }
