359	    fn framed(v: &Value) -> String {
360	        format!("event: {}\ndata: {v}\n\n", v["type"].as_str().unwrap())
361	    }
362	
363	    /// Step every record, give each completed hold `verdict` and each cut hold `BlockAll(cut)`,
364	    /// release every frame, then close. Returns the output, the decided calls and the stream.
365	    fn run(records: &[Record], verdict: impl Fn(&[ToolCall]) -> Verdict, cut: BlockCode) -> (String, Vec<ToolCall>, ResponsesStream) {
366	        let mut p = ResponsesStream::with_cap(1 << 20);
367	        let mut verdicts = Verdicts::new();
368	        let mut frames = Vec::new();
369	        let mut calls = Vec::new();
370	        for r in records {
371	            match p.step(r.clone(), &verdicts).ok().expect("canonical record") {
372	                Step::Terminal { frame, completed } => {
373	                    for (k, c) in completed {
374	                        verdicts.insert(k, verdict(&c));
375	                        calls.extend(c);
376	                    }
377	                    for k in p.incomplete() {
378	                        verdicts.entry(k).or_insert(Verdict::BlockAll(cut));
379	                    }
380	                    frames.push(frame);
381	                }
382	                Step::Frame { frame, .. } | Step::End(frame) | Step::UpstreamError(frame) => frames.push(frame),
383	            }
384	        }
385	        for k in p.incomplete() {
386	            verdicts.entry(k).or_insert(Verdict::BlockAll(cut));
387	        }
388	        let mut out = Vec::new();
389	        for f in frames {
390	            out.extend(p.release(f, &verdicts));
391	        }
392	        out.extend(p.closing(&verdicts));
393	        (String::from_utf8(out.concat()).unwrap(), calls, p)
394	    }
