400	    /// The `data:` payloads of an output, parsed. `[DONE]` is `Value::Null`.
401	    fn payloads(out: &str) -> Vec<Value> {
402	        out.split("\n\n")
403	            .filter_map(|f| f.lines().find_map(|l| l.strip_prefix("data: ")))
404	            .map(|d| serde_json::from_str(d).unwrap_or(Value::Null))
405	            .collect()
406	    }
