426	    #[test]
427	    fn allow_all_reemits_every_payload_with_its_event_line() {
428	        let evs = two_items();
429	        let mut recs = records(&evs);
430	        recs.push(done_rec());
431	        let (out, calls, _) = run(&recs, |c| Verdict::PerCall(vec![Decision::Allow; c.len()]), BlockCode::Truncated);
432	        let want: String = evs.iter().map(framed).collect::<String>() + "data: [DONE]\n\n";
433	        assert_eq!(out, want);
434	        assert_eq!(calls.iter().map(|c| (c.position, c.name.as_str())).collect::<Vec<_>>(), [(1, "rm")]);
435	        let (out, _, _) = run(&recs, |_| Verdict::AllowAll, BlockCode::Truncated);
436	        assert_eq!(out, want);
