439	    #[test]
440	    fn a_blocked_function_call_becomes_a_message_at_its_index() {
441	        let evs = two_items();
442	        let (out, _, _) = run(&records(&evs), |_| Verdict::PerCall(vec![Decision::Block { code: BlockCode::Policy }]), BlockCode::Truncated);
443	        assert!(!out.contains("CANARY") && !out.contains("\\\"p\\\""), "the blocked arguments leaked: {out}");
444	        let notice = r#"[paigasus] tool call "rm" was blocked (policy)."#;
445	        let got = payloads(&out);
446	        // The message item passes unchanged; the call becomes the four events of § 6.5.
447	        let message_frames = 6;
448	        assert_eq!(got[..2 + message_frames], evs[..2 + message_frames]);
449	        let added_seq = &evs[2 + message_frames]["sequence_number"];
450	        let done_seq = &evs[evs.len() - 2]["sequence_number"];
451	        let [a, b, c] = added_events(1, notice, Some(added_seq));
452	        assert_eq!(got[2 + message_frames..2 + message_frames + 4], [a, b, c, done_event(1, notice, Some(done_seq))]);
453	        let term = got.last().unwrap();
454	        assert_eq!(term["type"], "response.completed");
455	        assert_eq!(term["response"]["output"][1], completed_message(1, notice));
456	        assert_eq!(term["response"]["output"][0], evs.last().unwrap()["response"]["output"][0], "only the blocked index changes");
457	        assert_eq!(term["response"]["usage"], json!({"total_tokens": 9}), "no other field of the terminal changes");
458	        assert_eq!(got.len(), 2 + message_frames + 4 + 1, "every middle frame of the call is dropped");
459	        // Each rewritten frame has its own event line.
460	        assert!(
461	            out.contains("event: response.output_text.delta\ndata: {\"type\":\"response.output_text.delta\",\"item_id\":\"msg_paigasus_1\""),
462	            "{out}"
463	        );
464	    }
