476	    #[test]
477	    fn a_blocked_item_without_done_gets_a_synthesized_done() {
478	        let notice = r#"[paigasus] tool call "rm" was blocked (truncated)."#;
479	        let evs = cut_call();
480	        let seq = evs[2]["sequence_number"].clone();
481	        let want_done = done_event(0, notice, Some(&seq));
482	        // Before the terminal frame (release).
483	        let mut with_terminal = evs.clone();
484	        let mut open = with_terminal[2]["item"].clone();
485	        open["status"] = json!("in_progress");
486	        with_terminal.push(json!({"type": "response.incomplete", "sequence_number": 4, "response": {"id": "resp_1", "status": "incomplete", "output": [open]}}));
487	        let (out, calls, _) = run(&records(&with_terminal), block_all, BlockCode::Truncated);
488	        assert!(calls.is_empty(), "a cut hold is not decided");
489	        assert_eq!(
490	            types(&out)[2..],
491	            [
492	                "response.output_item.added",
493	                "response.content_part.added",
494	                "response.output_text.delta",
495	                "response.output_item.done",
496	                "response.incomplete"
497	            ]
