411	/// The per-kind rules of a client-run `done` item (R11–R14).
412	fn check_client(kind: ToolCallKind, open: &Open, added: &Map<String, Value>, done: &Map<String, Value>, completed: bool) -> Result<(), Deviation> {
413	    match kind {
414	        ToolCallKind::Function | ToolCallKind::Custom => {
415	            // R15 takes precedence over R11 (A3), and R12 is the same rule with `input`.
416	            if !completed {
417	                return Ok(());
418	            }
419	            let function = kind == ToolCallKind::Function;
420	            let (key, mismatch, added_label) = if function {
421	                ("arguments", "arguments_mismatch", "added_arguments")
422	            } else {
423	                ("input", "input_mismatch", "input_mismatch")
424	            };
425	            if !matches!(added.get(key), Some(Value::String(s)) if s.is_empty()) {
426	                return Err(Deviation(added_label));
427	            }
428	            let Some(Value::String(text)) = done.get(key) else { return Err(Deviation(mismatch)) };
429	            if !open.text.agrees(text) {
430	                return Err(Deviation(mismatch));
431	            }
432	            if function && !arguments_complete(text) {
433	                return Err(Deviation("incomplete_arguments"));
434	            }
435	        }
436	        ToolCallKind::Shell => {
437	            let bad = Deviation("shell_command_mismatch");
438	            let done_commands = shell_commands(done)?.map_or(&[][..], Vec::as_slice);
439	            // Ruling F2: `added` commands are `[]` or the `done` commands.
440	            if let Some(a) = shell_commands(added)?
441	                && !a.is_empty()
442	                && a.as_slice() != done_commands
443	            {
444	                return Err(bad);
445	            }
446	            if open.commands.len() != done_commands.len() {
447	                return Err(bad);
448	            }
449	            for (c, d) in open.commands.iter().zip(done_commands) {
450	                let Value::String(d) = d else { return Err(bad) };
451	                if c.done != Some(hash_str(d)) {
