728	    /// An item-scoped event between `added` and `done` (R6, R11–R14 ordering, R16).
729	    fn middle(&mut self, ty: &'static str, item_type: &'static str, v: &Value, ev: &Map<String, Value>) -> Result<Effect, Deviation> {
730	        let index = self.locate(ev)?;
731	        let open = self.open.as_mut().expect("locate found the open item");
732	        // Ruling T3a: a content part belongs to the item type its part names.
733	        let expected = if ty.starts_with("response.content_part.") {
734	            content_part_item(v).map_err(|_| Deviation("event_item_type"))?
735	        } else {
736	            item_type
737	        };
738	        if open.ty != expected {
739	            return Err(Deviation("event_item_type"));
740	        }
741	        // `response.shell_call_command.*` is the one item-scoped family with no `item_id`.
742	        let no_item_id = ty.starts_with("response.shell_call_command.");
743	        match ev.get("item_id") {
744	            Some(Value::String(s)) if *s == open.id => {}
745	            None if no_item_id => {}
746	            _ => return Err(Deviation("item_id_mismatch")),
747	        }
748	        // Function and custom streams are judged at `done`, where R15 can take precedence (A3).
749	        // An apply-patch diff and a shell command are judged here too.
750	        let diff_ok = match ty {
751	            "response.function_call_arguments.delta" | "response.custom_tool_call_input.delta" => {
752	                open.text.delta(ev.get("delta"));
753	                true
754	            }
755	            "response.function_call_arguments.done" => {
756	                open.text.done(ev.get("arguments"));
757	                true
758	            }
759	            "response.custom_tool_call_input.done" => {
760	                open.text.done(ev.get("input"));
761	                true
762	            }
763	            "response.apply_patch_call_operation_diff.delta" => open.text.delta(ev.get("delta")),
764	            "response.apply_patch_call_operation_diff.done" => open.text.done(ev.get("diff")),
765	            _ if no_item_id => {
766	                shell_event(&mut open.commands, ty, ev)?;
767	                true
768	            }
769	            _ => true,
770	        };
771	        if !diff_ok {
772	            return Err(Deviation("diff_mismatch"));
773	        }
774	        let client = matches!(open.class, ItemClass::ClientRun(_));
775	        Ok(Effect {
776	            frame: ItemFrame::Middle,
777	            item: client.then_some(index),
778	            ..Effect::other()
779	        })
780	    }
