782	    /// R9, R11–R15 and the subset rule at `response.output_item.done`.
783	    fn done(&mut self, ev: &Map<String, Value>) -> Result<Effect, Deviation> {
784	        let value = ev.get("item");
785	        let (item, item_type, _) = item_shape(value)?;
786	        let index = self.locate(ev)?;
787	        if identity(item) != self.items[index as usize].identity {
788	            return Err(Deviation("item_identity_changed"));
789	        }
790	        let open = self.open.take().expect("locate found the open item");
791	        let mut client = false;
792	        if let ItemClass::ClientRun(kind) = open.class {
793	            client = true;
794	            let added_value = open.added.as_ref().expect("a client-run item keeps its added item");
795	            let added = added_value.as_object().expect("item_shape checked the added item");
796	            // R15: a `done` whose `status` is not `"completed"` is a truncation. An absent `status`
797	            // is one too, except for an item type whose model has no `status` field (T4b).
798	            let completed = is_completed(item, item_type);
799	            check_client(kind, &open, added, item, completed)?;
800	            if !subset(added, item, true) {
801	                return Err(Deviation("added_done_differ"));
802	            }
803	            let call = tool_call(index, item, kind).map_err(|m| Deviation(if m.0 == "lossy_number" { "lossy_number" } else { "item_shape" }))?;
804	            if !completed {
805	                self.truncated = true;
806	            }
807	            self.held -= raw_len(added_value);
808	            if let Some(n) = self.names.last_mut() {
809	                *n = (index, call.display_name());
810	            }
811	            if !self.overflowed {
812	                self.held += call.arguments.len();
813	                self.calls.push(call);
814	                if self.held > self.cap {
815	                    // 749 D13: an outgrown hold keeps nothing and is never decided.
816	                    self.overflowed = true;
817	                    self.held -= std::mem::take(&mut self.calls).iter().map(|c| c.arguments.len()).sum::<usize>();
818	                }
819	            }
820	            self.items[index as usize].done_hash = value.map(hash_value);
821	        }
822	        self.items[index as usize].done = true;
823	        Ok(Effect {
824	            frame: ItemFrame::Done,
825	            item: client.then_some(index),
826	            ..Effect::other()
827	        })
828	    }
