3	//! The `POST /v1/responses` proxy handler (SMA-769 D3–D5, D8, D13, D15, § 7.2).
4	//!
5	//! The route is mounted only when `[responses] enabled = true` (D8); otherwise it is a 404. The
6	//! flow is the generic [`pipeline::proxy`]; this module gives the [`RESPONSES`] descriptor:
7	//!
8	//! - **Parse** (§ 7.2): a COPY of the body is read into [`ResponsesRequest`]. `input` must be a
9	//!   string or an array. D4 (`background: true`) is refused always; D3 (a non-null
10	//!   `previous_response_id`, `conversation` or `prompt`, or an `item_reference` input item) is
11	//!   refused only when interception is on. The pipeline calls the parse before `Limits::admit`,
12	//!   so a refused request uses no quota and is not charged. A JSON `null` and `background: false`
13	//!   pass (Review Focus 2).
14	//! - **D5:** the request body goes upstream byte-identical. The gateway does not set `store`.
15	//! - **Usage** (D14): the Responses readers of [`responses_usage`](super::responses_usage).
16	//! - **Terminal frame** (D13): [`RESPONSES_TERMINAL_SSE_ERROR`].
17	//! - **Limits** (D15): the interception limits with the record and hold caps of `[responses]`.
18	//!
19	//! Streaming obeys the same `stream_enabled` switch as chat (D9): the pipeline reads the one
20	//! shared capability.
21	
22	use axum::Extension;
23	use axum::extract::State;
24	use axum::response::{IntoResponse, Response};
25	use paigasus_gateway_core::{Format, Limits};
26	use serde::Deserialize;
27	use serde_json::Value;
28	
29	use super::AppState;
30	use super::error::GatewayError;
31	use super::interception::ToolInterception;
32	use super::pipeline::{self, Endpoint, RequestFacts};
33	use super::responses_usage::{self, ResponsesUsageScanner};
34	use super::usage::StreamUsage;
35	use crate::adapters::http::bytes::EnvelopeBytes;
36	use crate::adapters::http::dto::ResponsesRequest;
37	use crate::adapters::openai::UpstreamRoute;
38	use crate::domain::CallerContext;
39	
40	/// D13: the terminal SSE frame of a Responses stream that fails mid-flight. It is an `error`
41	/// event in the Responses shape, with the registry's kebab `upstream-error`. As with the chat
42	/// frame, the leading blank line ends a partly sent record, so the frame is a record of its own.
43	pub const RESPONSES_TERMINAL_SSE_ERROR: &str = "\n\nevent: error\ndata: {\"type\":\"error\",\"code\":\"upstream-error\",\"message\":\"upstream stream error\",\"param\":null}\n\n";
44	
45	/// Proxy a Responses request to the OpenAI upstream. The extractor rules are those of
46	/// [`chat_completions`](super::chat::chat_completions): [`EnvelopeBytes`] consumes the body, so it
47	/// comes last, and it answers an over-limit body (the `[responses] max_request_bytes` layer) with
48	/// a `413` inside the OpenAI envelope.
49	pub(crate) async fn create_response(State(state): State<AppState>, caller: Option<Extension<CallerContext>>, body: EnvelopeBytes) -> Response {
50	    let Some(Extension(caller)) = caller else {
51	        // Unreachable in practice — the auth middleware always attaches a CallerContext.
52	        return GatewayError::Internal.into_response();
53	    };
54	    pipeline::proxy(&RESPONSES, state, caller, body).await
55	}
