57	/// The descriptor of `POST /v1/responses`.
58	pub static RESPONSES: Endpoint = Endpoint {
59	    name: "responses",
60	    route: UpstreamRoute::Responses,
61	    format: Format::OpenAiResponses,
62	    parse: parse_responses,
63	    non_stream_usage: responses_usage::non_stream_usage,
64	    stream_usage: || StreamUsage::Responses(ResponsesUsageScanner::new()),
65	    terminal: RESPONSES_TERMINAL_SSE_ERROR,
66	    limits: responses_limits,
67	};
68	
69	/// D15: the interception limits with the record and hold caps of `[responses]`. The route is
70	/// mounted only when `state.responses` is `Some`, so the fallback to the shared limits is not
71	/// reached.
72	fn responses_limits(ti: &ToolInterception, state: &AppState) -> Limits {
73	    match &state.responses {
74	        Some(settings) => Limits {
75	            max_record_bytes: settings.max_record_bytes,
76	            max_held_bytes: settings.max_held_bytes,
77	            ..ti.limits
78	        },
79	        None => ti.limits,
80	    }
81	}
82	
83	/// Parse a COPY of the body (§ 7.2). The failure split is that of chat (SMA-588): a body that
84	/// cannot be read is `BadRequestBody`; a body that is JSON but not the request shape (not an
85	/// object, a field of the wrong type, an `input` that is not a string or an array) is
86	/// `InvalidRequestSchema`. Then D4 and D3, in the order of [`refuse_stateful`].
87	fn parse_responses(body: &[u8], interception: bool) -> Result<RequestFacts, GatewayError> {
88	    let value: Value = serde_json::from_slice(body).map_err(|e| match e.classify() {
89	        serde_json::error::Category::Data => GatewayError::InvalidRequestSchema,
90	        serde_json::error::Category::Syntax | serde_json::error::Category::Eof | serde_json::error::Category::Io => GatewayError::BadRequestBody,
91	    })?;
92	    // Coordinator ruling (fix round 1): a duplicate key must not decide D3 or D4. A duplicate
93	    // top-level `background` is refused in both modes (D4). With interception on, a duplicate key
94	    // at any depth is refused, because the turn facts and D3 would read the last value and the
95	    // upstream may read the first. With interception off the body passes as before.
96	    let dups = duplicates(body).ok_or(GatewayError::BadRequestBody)?;
97	    if dups.background {
98	        return Err(GatewayError::ResponsesStatefulNotSupported { param: "background" });
99	    }
100	    if interception && dups.any {
101	        return Err(GatewayError::InvalidRequestSchema);
102	    }
103	    let dto = ResponsesRequest::deserialize(&value).map_err(|_| GatewayError::InvalidRequestSchema)?;
104	    if !matches!(dto.input, None | Some(Value::String(_) | Value::Array(_))) {
105	        return Err(GatewayError::InvalidRequestSchema);
106	    }
107	    refuse_stateful(&dto, interception)?;
108	    Ok(RequestFacts {
109	        request_estimate: responses_usage::request_tokens_estimate(&value, body.len()),
110	        model: dto.model.unwrap_or_else(|| "-".to_owned()),
111	        stream: dto.stream.unwrap_or(false),
112	    })
113	}
114	
115	/// D4 always, then D3 when interception is on, in the order `background`,
116	/// `previous_response_id`, `conversation`, `prompt`, `input`. The first match names its `param`.
117	fn refuse_stateful(dto: &ResponsesRequest, interception: bool) -> Result<(), GatewayError> {
118	    let refuse = |param| Err(GatewayError::ResponsesStatefulNotSupported { param });
119	    if dto.background == Some(true) {
120	        return refuse("background");
121	    }
122	    if !interception {
123	        return Ok(());
124	    }
125	    if dto.previous_response_id.is_some() {
126	        return refuse("previous_response_id");
127	    }
128	    if dto.conversation.is_some() {
129	        return refuse("conversation");
130	    }
131	    if dto.prompt.is_some() {
132	        return refuse("prompt");
133	    }
134	    if let Some(Value::Array(items)) = &dto.input
135	        && items.iter().any(is_item_reference)
136	    {
137	        return refuse("input");
138	    }
139	    Ok(())
140	}
141	
142	/// An `item_reference` input item. Its `type` is optional in the API (openai-python 3.48.0
143	/// `ItemReference`: `id` required, `type` `Optional[Literal["item_reference"]]`). The only other
144	/// untyped item, the easy input message, always has a string `role`. So, failing closed, an item
145	/// with no string `type` is a reference unless its `role` is a string.
146	fn is_item_reference(item: &Value) -> bool {
147	    let Some(obj) = item.as_object() else { return false };
148	    match obj.get("type") {
149	        Some(Value::String(ty)) => ty == "item_reference",
150	        _ => !matches!(obj.get("role"), Some(Value::String(_))),
151	    }
152	}
153	
154	/// The duplicate keys of one request body.
155	#[derive(Debug, Default, PartialEq, Eq)]
156	struct Duplicates {
157	    /// Some object, at any depth, has a key twice.
158	    any: bool,
159	    /// The top-level object has `background` twice (D4).
160	    background: bool,
161	}
162	
163	/// Find the duplicate keys of `body`. serde_json keeps the last of two duplicate keys, and an
164	/// upstream may keep the first, so the D3 and D4 checks would read a different value than the
165	/// upstream does. Keys compare after JSON unescaping (`"a"` and `"a"` are one key). The walk
166	/// holds one key set per open object and no values. `None` when the body is not JSON; the caller
167	/// has already parsed it, so that does not occur.
168	fn duplicates(body: &[u8]) -> Option<Duplicates> {
169	    let mut found = Duplicates::default();
170	    let mut de = serde_json::Deserializer::from_slice(body);
171	    serde::de::DeserializeSeed::deserialize(Walk { found: &mut found, top: true }, &mut de).ok()?;
172	    Some(found)
173	}
174	
175	/// One value of the [`duplicates`] walk. `top` is true for the document's own value only.
176	struct Walk<'a> {
177	    found: &'a mut Duplicates,
178	    top: bool,
179	}
180	
181	impl<'de> serde::de::DeserializeSeed<'de> for Walk<'_> {
182	    type Value = ();
183	    fn deserialize<D: serde::Deserializer<'de>>(self, d: D) -> Result<(), D::Error> {
184	        d.deserialize_any(self)
185	    }
186	}
187	
188	impl<'de> serde::de::Visitor<'de> for Walk<'_> {
189	    type Value = ();
190	    fn expecting(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
191	        f.write_str("a JSON value")
192	    }
193	    fn visit_bool<E>(self, _: bool) -> Result<(), E> {
194	        Ok(())
195	    }
196	    fn visit_i64<E>(self, _: i64) -> Result<(), E> {
197	        Ok(())
198	    }
199	    fn visit_u64<E>(self, _: u64) -> Result<(), E> {
200	        Ok(())
201	    }
202	    fn visit_f64<E>(self, _: f64) -> Result<(), E> {
203	        Ok(())
204	    }
205	    fn visit_str<E>(self, _: &str) -> Result<(), E> {
206	        Ok(())
207	    }
208	    fn visit_unit<E>(self) -> Result<(), E> {
209	        Ok(())
210	    }
211	    fn visit_seq<A: serde::de::SeqAccess<'de>>(self, mut seq: A) -> Result<(), A::Error> {
212	        while seq.next_element_seed(Walk { found: &mut *self.found, top: false })?.is_some() {}
213	        Ok(())
214	    }
215	    fn visit_map<A: serde::de::MapAccess<'de>>(self, mut map: A) -> Result<(), A::Error> {
216	        let mut seen = std::collections::HashSet::new();
217	        while let Some(key) = map.next_key::<String>()? {
218	            if seen.contains(&key) {
219	                self.found.any = true;
220	                self.found.background |= self.top && key == "background";
221	            }
222	            map.next_value_seed(Walk { found: &mut *self.found, top: false })?;
223	            seen.insert(key);
224	        }
225	        Ok(())
226	    }
227	}
