42	/// What the pipeline needs from a parsed request.
43	pub struct RequestFacts {
44	    /// The model name, for the request log.
45	    pub model: String,
46	    /// Whether the caller asked for a stream.
47	    pub stream: bool,
48	    /// The token estimate for the request side of the charge.
49	    pub request_estimate: u64,
50	}
51	
52	/// The descriptor of one OpenAI-shaped route.
53	pub struct Endpoint {
54	    /// The endpoint name. `"chat_completions"` for chat. Task 15 uses it as a log field and a
55	    /// metric label.
56	    pub name: &'static str,
57	    /// The upstream route this endpoint forwards to.
58	    pub route: UpstreamRoute,
59	    /// The wire format the interceptor reads.
60	    pub format: Format,
61	    /// Parse a COPY of the body. The second argument says whether interception is enabled.
62	    pub parse: fn(&[u8], bool) -> Result<RequestFacts, GatewayError>,
63	    /// The usage a non-stream 2xx body reports.
64	    pub non_stream_usage: fn(&[u8]) -> BodyUsage,
65	    /// A new usage reader for one stream.
66	    pub stream_usage: fn() -> StreamUsage,
67	    /// The terminal SSE frame for a mid-stream upstream failure.
68	    pub terminal: &'static str,
69	    /// The interception limits for this endpoint.
70	    pub limits: fn(&ToolInterception, &AppState) -> Limits,
71	}
72	
73	/// Proxy one request through `endpoint`. See the module docs for the rules that bind it.
74	///
75	/// The body arrives as the house [`EnvelopeBytes`] that the handler extracted, and is unwrapped
76	/// here. The wrapped bytes are the ORIGINAL request bytes, and they go upstream unchanged (D5).
77	pub(crate) async fn proxy(endpoint: &'static Endpoint, state: AppState, caller: CallerContext, body: EnvelopeBytes) -> Response {
78	    let EnvelopeBytes(body) = body;
79	    // Parse a COPY only to read the facts; the ORIGINAL `body` bytes flow upstream verbatim.
80	    // The parse function splits its failures (SMA-588): a body that PARSED but did not match the
81	    // type is reported distinctly from one that could not be read at all.
82	    let RequestFacts { model, stream, request_estimate } = match (endpoint.parse)(&body, state.tool_interception.is_some()) {
83	        Ok(facts) => facts,
84	        Err(e) => return e.into_response(),
85	    };
86	
87	    // SMA-505 D9: streaming is a request PARAMETER, not a route, so a disabled capability is
88	    // enforced here rather than by unmounting. Checked before any egress call, so a refused
89	    // request never reaches the upstream or its rate limit.
90	    if stream && !state.capabilities.chat_stream {
91	        return GatewayError::StreamingDisabled.into_response();
92	    }
93	
94	    // SMA-677 D9: the limits run after the body and streaming checks and just before egress, so a
95	    // refused body never uses quota. `None` (no `[limits]` table) skips them entirely (A6).
96	    let mut guard = match &state.limits {
97	        None => None,
98	        Some(limits) => match limits.admit_for(&caller, endpoint.name).await {
99	            Ok(guard) => Some(guard),
100	            Err(refusal) => {
101	                // The refusal metric is the operator's signal; this line stays at debug.
102	                tracing::debug!(principal = %caller.principal_prn, scope = %caller.scope_prn, reason = refusal.label(), endpoint = endpoint.name, "chat completion refused by a limit");
103	                return GatewayError::from(refusal).into_response();
104	            }
105	        },
106	    };
107	    if let Some(guard) = guard.as_mut() {
108	        guard.set_request_estimate(request_estimate);
109	        // The ids exist here; inside the stream `current_ids()` is `None` (SMA-504 § 4.3).
110	        guard.set_ids(paigasus_observability::current_ids());
111	        guard.set_endpoint(endpoint.name);
112	        guard.mark_sent();
113	    }
114	
115	    // SMA-749: capture what the decider needs while the request ids still exist (SMA-504 § 4.3:
116	    // inside the stream they are `None`). Parsed from the same raw bytes that go upstream.
117	    // `None` when interception is off: nothing is parsed or constructed (D27).
118	    let interception = state.tool_interception.clone().map(|ti| {
119	        let limits = (endpoint.limits)(&ti, &state);
120	        let turn = Arc::new(paigasus_gateway_core::parse_request(endpoint.format, &body));
121	        let request_id = paigasus_observability::current_ids().map(|ids| ids.request_id.to_string());
122	        let ctx = Arc::new(paigasus_gateway_core::DecisionContext::new(caller.principal_prn.clone(), caller.scope_prn.clone(), request_id));
123	        (ti, limits, ctx, turn)
124	    });
125	
126	    let started = Instant::now();
127	    // EGRESS HYGIENE: only the raw body bytes cross the boundary — never the caller's headers.
128	    let result = state.openai.send(endpoint.route, body, stream).await;
129	
130	    let (response, status) = match result {
131	        Ok(ChatResponse::Full { status, body: upstream_body }) => {
132	            // Non-stream: the upstream head AND body have both landed, so this is a genuine
133	            // full-request latency, not just TTFB (see the NOTE on the stream arm below).
134	            record_upstream_call(status, started, endpoint.name);
135	            // A4: a 2xx reads a COPY of the body for its usage; a non-2xx charges nothing.
136	            if let Some(guard) = guard.as_mut() {
137	                if status.is_success() {
138	                    match (endpoint.non_stream_usage)(&upstream_body) {
139	                        BodyUsage::Reported(total) => guard.set_reported(total),
140	                        BodyUsage::Completion(tokens) => guard.set_completion_estimate(tokens),
141	                    }
142	                } else {
143	                    guard.mark_no_charge();
144	                }
145	            }
146	            // SMA-749 § 5.2: the guard read the ORIGINAL body above (D24); interception runs after.
147	            let outcome = match &interception {
148	                Some((ti, limits, ctx, turn)) if status.is_success() => interception::intercept_body(ti, *limits, endpoint.format, Arc::clone(ctx), Arc::clone(turn), &upstream_body).await,
149	                _ => interception::BodyOutcome::Forward { rewritten: None, report: None },
150	            };
151	            match outcome {
152	                interception::BodyOutcome::Refuse => {
153	                    let resp = GatewayError::ToolInterceptionMalformedResponse.into_response();
154	                    let status = resp.status();
155	                    (resp, status)
156	                }
157	                interception::BodyOutcome::Forward { rewritten, report } => {
158	                    let out = rewritten.unwrap_or(upstream_body);
159	                    // Forward the upstream status + body VERBATIM (or rewritten by a block),
160	                    // including a non-2xx OpenAI error envelope.
161	                    let mut resp = (status, [(header::CONTENT_TYPE, "application/json")], out).into_response();
162	                    if let Some(r) = report
163	                        && let Ok(v) = axum::http::HeaderValue::from_str(&r)
164	                    {
165	                        resp.headers_mut().insert("paigasus-tool-decisions", v);
166	                    }
167	                    (resp, status)
168	                }
169	            }
170	        }
171	        Ok(ChatResponse::Stream { status, stream: upstream }) => {
172	            // NOTE: for `stream:true` this records TTFB (time-to-first-byte / response head), NOT
173	            // stream completion — the call is considered "done" for metrics purposes the moment
174	            // the upstream response head arrives. A mid-stream SSE failure (handled below by the
175	            // terminal-error adapter, once the 200 head is already committed) is NOT re-counted
176	            // here — it has no separate HTTP status to attribute.
177	            record_upstream_call(status, started, endpoint.name);
178	            let resp = if status.is_success() {
179	                // Success stream: SSE passthrough with the mid-stream terminal-error adapter.
180	                //
181	                // SMA-504 spec §4.3, situation 3: `current_ids() == None` from here on. The
182	                // `CorrelationLayer`'s task-local scope covers the request-HEAD future only, and
183	                // that future already resolved to this `Response<Body>` the moment this line
184	                // runs — hyper polls the `Body::from_stream` future (and therefore
185	                // `terminal_sse_error_stream` below) AFTERWARDS, outside the scope. Anything
186	                // added inside the stream adapter — a log line, a metric — will see no ids.
187	                let usage = (endpoint.stream_usage)();
188	                let out = match interception {
189	                    // SMA-749: the interceptor owns the terminal frame from here on (D17).
190	                    Some((ti, limits, ctx, turn)) => Body::from_stream(interception::intercepted_stream(
191	                        endpoint.format,
192	                        limits,
193	                        upstream,
194	                        guard.take(),
195	                        usage,
196	                        ti,
197	                        ctx,
198	                        turn,
199	                        endpoint.terminal.as_bytes(),
200	                    )),
201	                    None => Body::from_stream(terminal_sse_error_stream(upstream, guard.take(), usage, endpoint.terminal)),
202	                };
203	                (status, [(header::CONTENT_TYPE, "text/event-stream")], out).into_response()
204	            } else {
205	                // Non-2xx `stream:true` request: OpenAI answers with a JSON error body (NOT SSE), so
206	                // forward it as an error passthrough — no SSE terminal-error wrapping applies.
207	                if let Some(guard) = guard.as_mut() {
208	                    guard.mark_no_charge();
209	                }
210	                (status, [(header::CONTENT_TYPE, "application/json")], Body::from_stream(upstream)).into_response()
211	            };
212	            (resp, status)
213	        }
214	        Err(err) => {
215	            // Connect/transport/build → 502; timeout → 504 (see `GatewayError::from`). No upstream
216	            // HTTP status exists in this case at all, so record under the MAPPED gateway status
217	            // instead (still a `status_class` derived from an HTTP status, per the global
